module.exports=[52095,a=>{a.v({nav:{services:"Servicios",success_cases:"Casos de Éxito",about:"Nosotros",contact:"Contacto"},hero:{title:"Potenciando tu Futuro Digital",subtitle:"Soluciones tecnológicas adaptadas a tus objetivos de negocio. Innovemos juntos.",cta:"Comenzar"},services:{title:"Nuestros Servicios",description:"Consultoría tecnológica integral para acelerar la transformación de tu negocio.",items:[{title:"Transformación Cloud",desc:"Ayudamos a las empresas a migrar, gestionar y escalar su infraestructura en la nube de forma eficiente y segura."},{title:"Estrategia de Datos",desc:"Diseñamos e implementamos arquitecturas de datos modernas, analítica y modelos de gobernanza para extraer valor de sus datos."},{title:"IA y Automatización",desc:"Aproveche la IA y la automatización inteligente para optimizar las operaciones y mejorar la toma de decisiones."}]},success_cases:{title:"Casos de Éxito",description:"Impacto en el mundo real en diversas industrias.",items:[{title:"Chatbot Coach de Habilidades Blandas con IA",desc:"Diseñamos e implementamos un chatbot impulsado por IA usando arquitectura RAG, integrado con Slack y Azure Speech Services. Desplegado en AKS con Cosmos DB."},{title:"Automatización de Infraestructura con Terraform y AWS",desc:"Automatizamos entornos AWS multi-cuenta usando Terraform. Implementamos pipelines CI/CD y gestionamos despliegues con flujos de trabajo GitOps."},{title:"Sistema de ML en GCP",desc:"Construimos un sistema de ML escalable en Google Cloud Platform usando Vertex AI, BigQuery y Cloud Functions. Soporte para inferencia en batch y tiempo real."},{title:"Pipelines de Datos en Databricks y Airflow",desc:"Desarrollamos pipelines de datos confiables usando PySpark en Databricks y orquestados con Airflow para un cliente minorista global."},{title:"Analítica de Streaming con Kafka y Flink",desc:"Diseñamos una plataforma de analítica en tiempo real para procesamiento de eventos usando Kafka y Apache Flink para una empresa fintech."},{title:"Dashboard de Analítica Power BI para Retail",desc:"Construimos dashboards interactivos en Power BI para rastrear KPIs clave de retail, optimizando inventario y operaciones regionales."},{title:"Visión Artificial para Petróleo y Gas",desc:"Implementamos una solución de visión artificial para detectar anomalías en equipos usando modelos de deep learning. Mejoramos la eficiencia de inspección."},{title:"Detección de Fraude para Banca",desc:"Desarrollamos modelos de detección de fraude en tiempo real con técnicas de aprendizaje de conjunto sobre datos de transacciones a gran escala."},{title:"Plataforma NLP para EdTech",desc:"Construimos una plataforma de Q&A basada en NLP para una empresa de EdTech, aplicando modelos transformer para personalizar rutas de estudio."}]},about:{title:"Sobre Nosotros",paragraphs:["Somos un equipo de profesionales con una base multidisciplinaria y una trayectoria comprobada en diversas industrias. Con formación que va desde la física y la economía hasta las ciencias de la computación, nuestra experiencia principal radica en la resolución de problemas, la comunicación efectiva y el trabajo en equipo. Nos especializamos en desarrollar soluciones confiables basadas en datos con sustancial experiencia en aprendizaje automático, incluyendo análisis de series temporales, visión artificial y procesamiento de lenguaje natural.","Como aprendices auto-motivados, hemos dominado temas avanzados como la inteligencia artificial y la computación en la nube. Nuestra cartera incluye proyectos prácticos para los sectores de retail, banca, finanzas, salud, petróleo y gas, energía, govtech y edtech. Cerramos la brecha entre las partes interesadas técnicas y no técnicas, y somos competentes en las principales plataformas en la nube como GCP, Azure, AWS e IBM Cloud."],tags:["GCP","Azure","AWS","IBM Cloud","Aprendizaje Automático","NLP","Visión Artificial","Series Temporales","Terraform","Databricks","Kafka","Power BI"]},contact:{title:"Ponte en Contacto",name_label:"Nombre",name_placeholder:"Tu nombre",email_label:"Correo electrónico",email_placeholder:"tu@email.com",message_label:"Mensaje",message_placeholder:"Cuéntanos sobre tu proyecto...",cta:"Enviar Mensaje",email:"contact@deff-consulting.org"},footer:{rights:"Todos los derechos reservados.",contact_text:"Contáctanos en"}})}];

